import numpy as np

def relu(z):
    return np.maximum(0, z)

def sigmoid(z):
    # Clip values to reduce overflow in exp for extreme inputs.
    z = np.clip(z, -500, 500)
    return 1 / (1 + np.exp(-z))

def neuron(x, weights, bias, activation='relu'):
    x = np.asarray(x, dtype=float)
    weights = np.asarray(weights, dtype=float)

    if x.shape != weights.shape:
        raise ValueError('Inputs and weights must have the same shape.')

    z = np.dot(x, weights) + bias

    if activation == 'relu':
        output = relu(z)
    elif activation == 'sigmoid':
        output = sigmoid(z)
    elif activation == 'linear':
        output = z
    else:
        raise ValueError('Unsupported activation function.')

    return z, output

x = [1.5, 2.0, -1.0]
weights = [0.4, 0.2, -0.5]
bias = 0.1

z, output = neuron(x, weights, bias, activation='relu')
print('Pre-activation:', z)
print('Neuron output:', output)
